INSERT INTO `finding_messages` VALUES ('MSG_DISK_CORRECTED_ERRORS','Storage reliability needs attention','PCTOZ found storage reliability indicators on {disk_model} that deserve attention.','Back up important data and run a detailed SMART health check before relying on this drive for critical data.'),('MSG_DISK_TEMP_CRITICAL','Storage temperature is too high','{disk_model} is operating at {temperature_c}┬░C.','Reduce disk activity if practical, check cooling immediately, and recheck the temperature before continued heavy use.'),('MSG_DISK_TEMP_HIGH','Storage temperature needs attention','{disk_model} is operating at {temperature_c}┬░C.','Check airflow, dust buildup, fan operation and surrounding temperature. Recheck the drive temperature after corrective action.'),('MSG_DISK_UNCORRECTED_ERRORS','Storage reliability warning','PCTOZ detected uncorrected read errors on {disk_model}.','Back up important data immediately and avoid unnecessary disk activity until the drive is checked.'),('MSG_HDD_SMART_PENDING','Storage reliability warning','SMART data for {disk_model} reports pending sectors.','Back up important data immediately and run a detailed SMART test before relying on this drive.'),('MSG_HDD_SMART_REALLOCATED','Storage reliability needs attention','SMART data for {disk_model} reports reallocated sectors.','Back up important data and monitor the drive. Run a detailed SMART test if the count increases or other storage symptoms appear.'),('MSG_HDD_SMART_UNCORRECTABLE','Storage reliability warning','SMART data for {disk_model} reports uncorrectable sectors.','Back up important data immediately and avoid unnecessary disk activity until the drive is checked.'),('MSG_LOW_SPACE','Low free space on Windows drive','Your Windows drive has only {system_drive_free_gb} GB free out of {system_drive_size_gb} GB ({system_drive_free_pct}% free).','Freeing some space is advisable. Check what is using the space before deleting anything important.'),('MSG_NVME_CRITICAL_WARNING','NVMe reliability warning','The NVMe drive {disk_model} reports a critical SMART/NVMe warning.','Back up important data immediately and run a detailed NVMe health check before relying on this drive.'),('MSG_NVME_MEDIA_ERRORS','NVMe media errors detected','The NVMe drive {disk_model} reports media or data-integrity errors.','Back up important data immediately and run a detailed NVMe health check before continued use.'),('MSG_RAM_FREE_SLOTS','Memory expansion available','Windows reports {ram_slots_reported} RAM slots: {ram_slots_used} used and {ram_slots_free} reported free.','No action is required from this information alone. If later diagnosis shows insufficient memory, expansion appears possible.');
/*!40000 ALTER TABLE `finding_messages` ENABLE KEYS */;
UNLOCK TABLES;

