--
-- Table structure for table `observations`
--

DROP TABLE IF EXISTS `observations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `observations` (
  `observation_id` bigint(20) NOT NULL AUTO_INCREMENT,
  `session_id` bigint(20) NOT NULL,
  `node_visit_id` bigint(20) DEFAULT NULL,
  `field_code` varchar(100) NOT NULL,
  `value_number` decimal(18,4) DEFAULT NULL,
  `value_text` text DEFAULT NULL,
  `unit` varchar(30) DEFAULT NULL,
  `source_type` enum('CUSTOMER','COLLECTOR','WINDOWS','TOOL','TECHNICIAN') NOT NULL,
  `source_detail` varchar(100) DEFAULT NULL,
  `confidence` varchar(20) DEFAULT NULL,
  `observed_at` datetime DEFAULT current_timestamp(),
  `technician_reviewed` tinyint(1) DEFAULT 0,
  `technician_value` text DEFAULT NULL,
  `technician_comment` text DEFAULT NULL,
  `issue_flag` tinyint(1) DEFAULT 0,
  `issue_status` varchar(30) DEFAULT NULL,
  PRIMARY KEY (`observation_id`),
  KEY `session_id` (`session_id`),
  CONSTRAINT `observations_ibfk_1` FOREIGN KEY (`session_id`) REFERENCES `diagnostic_sessions` (`session_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3612 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

