--
-- Table structure for table `session_findings`
--

DROP TABLE IF EXISTS `session_findings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `session_findings` (
  `session_finding_id` bigint(20) NOT NULL AUTO_INCREMENT,
  `session_id` bigint(20) NOT NULL,
  `finding_rule_id` bigint(20) DEFAULT NULL,
  `finding_code` varchar(100) NOT NULL,
  `severity` varchar(20) NOT NULL,
  `rendered_title` varchar(255) DEFAULT NULL,
  `rendered_body` text DEFAULT NULL,
  `generated_at` datetime DEFAULT current_timestamp(),
  `rendered_recommendation` text DEFAULT NULL,
  `source_entity_type` varchar(30) DEFAULT NULL,
  `source_entity_id` bigint(20) DEFAULT NULL,
  `disk_finding_rule_id` bigint(20) DEFAULT NULL,
  `rule_family` varchar(30) DEFAULT NULL,
  PRIMARY KEY (`session_finding_id`),
  KEY `session_id` (`session_id`),
  KEY `finding_rule_id` (`finding_rule_id`),
  KEY `fk_session_findings_disk_rule` (`disk_finding_rule_id`),
  CONSTRAINT `fk_session_findings_disk_rule` FOREIGN KEY (`disk_finding_rule_id`) REFERENCES `disk_finding_rules` (`disk_finding_rule_id`),
  CONSTRAINT `session_findings_ibfk_1` FOREIGN KEY (`session_id`) REFERENCES `diagnostic_sessions` (`session_id`),
  CONSTRAINT `session_findings_ibfk_2` FOREIGN KEY (`finding_rule_id`) REFERENCES `finding_rules` (`finding_rule_id`)
) ENGINE=InnoDB AUTO_INCREMENT=387 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
