INSERT INTO `tree_nodes` VALUES ('BOOT-A040','BOOT','ACTION','Close or disable only clearly unnecessary startup applications, then restart the computer.','Perform a safe startup-load experiment',NULL,'BOOT-Q050',1),('BOOT-E060','BOOT','END','Startup load appears to have contributed to the slowdown. The computer improved after reducing unnecessary startup activity.','Successful self-care terminal result',NULL,NULL,1),('BOOT-Q001','BOOT','Q','After the Windows desktop appears, does the computer remain slow for several minutes?','Determine whether the startup slowdown continues after Windows appears',NULL,NULL,1),('BOOT-Q020','BOOT','Q','During the slow period, which description best matches what was observed?','Record the principal startup-load observation',NULL,NULL,1),('BOOT-Q050','BOOT','Q','After restarting, is the computer noticeably faster?','Measure the result of the startup intervention',NULL,NULL,1),('BOOT-R030','BOOT','DECIDE','Evaluating the startup observation...','Interpret the collected startup observation',NULL,NULL,1),('BOOT-S010','BOOT','SHOW','We will now check whether startup activity is causing the slowdown.','Explain the next diagnostic stage',NULL,'BOOT-Q020',1),('DISK-A030','DISK','ACTION','Avoid unnecessary use of the computer. Back up important accessible data if this can be done safely, or obtain technician assistance.','Protect data before further diagnosis',NULL,'SHOP-E001',1),('DISK-Q001','DISK','Q','Have you noticed any serious storage symptoms?','Look for possible drive-failure symptoms before performance testing',NULL,NULL,1),('DISK-R010','DISK','DECIDE','Evaluating the storage symptoms...','Determine whether normal troubleshooting should stop',NULL,NULL,1),('DISK-S020','DISK','SHOW','The symptoms may indicate a storage-device problem. Protecting important data is more important than trying speed-up procedures.','Warn user before further testing',NULL,'DISK-A030',1),('DISK-S040','DISK','SHOW','No immediate storage-failure symptom was identified from these answers.','Allow normal disk-performance investigation to continue',NULL,'REMOTE-E001',1),('REMOTE-E001','REMOTE','END','The cause is not clear enough for safe self-care. Technician-assisted diagnosis is recommended.','Escalate uncertain case to technician',NULL,NULL,1),('ROOT-Q001','ROOT','Q','Are you currently using the computer that has the problem?','Determine whether automatic collection is allowed',NULL,NULL,1),('ROOT-Q020','ROOT','Q','What problem are you having?','Identify the first diagnostic branch',NULL,NULL,1),('ROOT-RUN010','ROOT','ACTION','Run PCTOZ PC Check on this computer, then upload the result.','Collect system information from the affected computer','PC_CHECK_UPLOAD',NULL,1),('ROOT-S015','ROOT','SHOW','PC check completed.','Show collector summary and automatically detected findings',NULL,'ROOT-Q020',1),('SHOP-E001','SHOP','END','Physical or technician-assisted storage diagnosis is recommended before further corrective work.','Terminal technician-care result',NULL,NULL,1),('SLOW-Q001','SLOW','Q','What seems slow?','Identify which part of the computer experience is slow',NULL,NULL,1);
